import{_ as n,a0 as s,w as p,s as d,ao as i,I as e,a1 as l,A as o,x as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"在樹莓派上玩懷舊遊戲的 5 種方法 | LCTT x X-CMD","titleTemplate":false,"description":"在樹莓派上玩懷舊遊戲的 5 種方法 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在樹莓派上玩懷舊遊戲的 5 種方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在樹莓派上玩懷舊遊戲的 5 種方法 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20180924 5 ways to play old-school games on a Raspberry Pi","title":"在樹莓派上玩懷舊遊戲的 5 種方法","tag":"201907","desc":""},"relativePath":"201907/20180924 5 ways to play old-school games on a Raspberry Pi.md","filePath":"[post].md"}'),b={name:"201907/20180924 5 ways to play old-school games on a Raspberry Pi.md"};function m(u,a,f,h,P,x){const t=s("Link");return p(),d("div",null,[a[50]||(a[50]=i('<h1 id="在樹莓派上玩懷舊遊戲的-5-種方法" tabindex="-1">在樹莓派上玩懷舊遊戲的 5 種方法 <a class="header-anchor" href="#在樹莓派上玩懷舊遊戲的-5-種方法" aria-label="Permalink to “在樹莓派上玩懷舊遊戲的 5 種方法”">​</a></h1><blockquote><p>使用這些用於樹莓派的開源平台來重温遊戲的黃金時代。</p></blockquote><p><img src="https://d3avoj45mekucs.cloudfront.net/rojakdaily/media/jessica-chua/lifestyle/retro%20gaming%20comeback/retro-video-game-event.jpg" alt=""></p><p>他們使它們不像過去那樣子了，對吧？我是説，電子遊戲。</p><p>當然，現在的設備更強大了。<ruby>賽達爾公主<rt>Princess Zelda</rt></ruby>在過去每個邊只有 16 個像素，而現在的圖像處理能力足夠處理她頭上的每根頭髮。今天的處理器打敗 1988 年的處理器簡直不費吹灰之力。</p><p>但是你知道缺少什麼嗎？樂趣。</p><p>你有數之不盡的遊戲，按下一個按鈕就可以完成教程任務。可能有故事情節，當然殺死壞蛋也可以不需要故事情節，你需要的只是跳躍和射擊。因此，毫不奇怪，樹莓派最持久的流行用途之一就是重温上世紀八九十年代的 8 位和 16 位遊戲的黃金時代。但從哪裏開始呢？</p><p>在樹莓派上有幾種方法可以玩懷舊遊戲。每一種都有自己的優點和缺點，我將在這裏討論這些。</p><h3 id="retropie" tabindex="-1">RetroPie <a class="header-anchor" href="#retropie" aria-label="Permalink to “RetroPie”">​</a></h3>',9)),e("p",null,[l(t,{href:"https://retropie.org.uk/"},{default:o(()=>[...a[0]||(a[0]=[r("RetroPie",-1)])]),_:1}),a[1]||(a[1]=r(" 可能是樹莓派上最受歡迎的復古遊戲平台。它是一個可靠的萬能選手，是模擬經典桌面和控制台遊戲系統的絕佳選擇。",-1))]),a[51]||(a[51]=e("p",null,[e("img",{src:"https://retropie.org.uk/wp-content/uploads/2016/04/Amiga_Gameplay_2.png",alt:""})],-1)),a[52]||(a[52]=e("h4",{id:"介紹",tabindex:"-1"},[r("介紹 "),e("a",{class:"header-anchor",href:"#介紹","aria-label":"Permalink to “介紹”"},"​")],-1)),e("p",null,[a[5]||(a[5]=r("RetroPie 構建在 ",-1)),l(t,{href:"https://www.raspbian.org/"},{default:o(()=>[...a[2]||(a[2]=[r("Raspbian",-1)])]),_:1}),a[6]||(a[6]=r(" 上運行。如果你願意，它也可以安裝在現有的 Raspbian 鏡像上。它使用 ",-1)),l(t,{href:"https://emulationstation.org/"},{default:o(()=>[...a[3]||(a[3]=[r("EmulationStation",-1)])]),_:1}),a[7]||(a[7]=r(" 作為開源仿真器庫（包括 ",-1)),l(t,{href:"https://www.libretro.com/"},{default:o(()=>[...a[4]||(a[4]=[r("Libretro",-1)])]),_:1}),a[8]||(a[8]=r(" 仿真器）的圖形前端。",-1))]),a[53]||(a[53]=e("p",null,"不過，你要玩遊戲其實並不需要理解上面的任何一個詞。",-1)),a[54]||(a[54]=e("h4",{id:"它有什麼好處",tabindex:"-1"},[r("它有什麼好處 "),e("a",{class:"header-anchor",href:"#它有什麼好處","aria-label":"Permalink to “它有什麼好處”"},"​")],-1)),a[55]||(a[55]=e("p",null,"入門很容易。你需要做的就是將鏡像刻錄到 SD 卡，配置你的控制器、複製遊戲，然後開始殺死壞蛋。",-1)),a[56]||(a[56]=e("p",null,"它的龐大用户羣意味着有大量的支持和信息，活躍的在線社區也可以求助問題。",-1)),a[57]||(a[57]=e("p",null,"除了隨 RetroPie 鏡像一起安裝的仿真器之外，還有一個可以從包管理器安裝的龐大的仿真器庫，並且它一直在增長。RetroPie 還提供了用户友好的菜單系統來管理這些，可以節省你的時間。",-1)),e("p",null,[a[11]||(a[11]=r("從 RetroPie 菜單中可以輕鬆添加 Kodi 和配備了 Chromium 瀏覽器的 Raspbian 桌面。這意味着你的這套復古遊戲裝備也適於作為家庭影院、",-1)),l(t,{href:"https://www.youtube.com/"},{default:o(()=>[...a[9]||(a[9]=[r("YouTube",-1)])]),_:1}),a[12]||(a[12]=r("、",-1)),l(t,{href:"https://soundcloud.com/"},{default:o(()=>[...a[10]||(a[10]=[r("SoundCloud",-1)])]),_:1}),a[13]||(a[13]=r(" 以及所有其它“休息室電腦”產品。",-1))]),a[58]||(a[58]=i('<p>RetroPie 還有許多其它自定義選項：你可以更改菜單中的圖形，為不同的模擬器設置不同的控制手柄配置，使你的樹莓派文件系統的所有內容對你的本地 Windows 網絡可見等等。</p><p>RetroPie 建立在 Raspbian 上，這意味着你可以探索這個樹莓派最受歡迎的操作系統。你所發現的大多數樹莓派項目和教程都是為 Raspbian 編寫的，因此可以輕鬆地自定義和安裝新內容。我已經使用我的 RetroPie 裝備作為無線橋接器，在上面安裝了 MIDI 合成器，自學了一些 Python，更重要的是，所有這些都沒有影響它作為遊戲機的用途。</p><h4 id="它有什麼不太好的" tabindex="-1">它有什麼不太好的 <a class="header-anchor" href="#它有什麼不太好的" aria-label="Permalink to “它有什麼不太好的”">​</a></h4><p>RetroPie 的安裝簡單和易用性在某種程度上是一把雙刃劍。你可以在 RetroPie 上玩了很長時間，而甚至沒有學習過哪怕像 <code>sudo apt-get</code> 這樣簡單的東西，但這也意味着你錯過了很多樹莓派的體驗。</p><p>但不一定必須如此；當你需要時，命令列仍然存在於底層，但是也許用户與 Bash shell 有點隔離，而使它最終並沒有看上去那麼可怕、另外，RetroPie 的主菜單隻能通過控制手柄操作，當你沒有接入手柄時，這可能很煩人，因為你一直將該系統用於遊戲之外的事情。</p><h4 id="它適用於誰" tabindex="-1">它適用於誰? <a class="header-anchor" href="#它適用於誰" aria-label="Permalink to “它適用於誰?”">​</a></h4><p>任何想直接玩一些遊戲的人，任何想擁有最大、最好的模擬器庫的人，以及任何想在不玩遊戲的時候開始探索 Linux 的人。</p><h3 id="recalbox" tabindex="-1">Recalbox <a class="header-anchor" href="#recalbox" aria-label="Permalink to “Recalbox”">​</a></h3>',8)),e("p",null,[l(t,{href:"https://www.recalbox.com/"},{default:o(()=>[...a[14]||(a[14]=[r("Recalbox",-1)])]),_:1}),a[15]||(a[15]=r(" 是一個較新的樹莓派開源模擬器套件。它還支持其它基於 ARM 的小型計算機。",-1))]),a[59]||(a[59]=i('<p><img src="https://www.recalbox.com/images/features/4playermodo_hu5438825b9b6d1014226d20d231e650c2_230970_500x0_resize_q75_box.jpeg" alt=""></p><h4 id="介紹-1" tabindex="-1">介紹 <a class="header-anchor" href="#介紹-1" aria-label="Permalink to “介紹”">​</a></h4><p>與 Retropie 一樣， Recalbox 基於 EmulationStation 和 Libretro。它的不同之處在於它不是基於 Raspbian 構建的，而是基於它自己的 Linux 發行版：RecalboxOS。</p><h4 id="它有什麼好處-1" tabindex="-1">它有什麼好處 <a class="header-anchor" href="#它有什麼好處-1" aria-label="Permalink to “它有什麼好處”">​</a></h4><p>Recalbox 的設置比 RetroPie 更容易。你甚至不需要做 SD 卡鏡像；只需複製一些文件即可。它還為一些遊戲控制器提供開箱即用的支持，可以讓你更快地開始遊戲。它預裝了 Kodi。這是一個現成的遊戲和媒體平台。</p><h4 id="它有什麼不太好的-1" tabindex="-1">它有什麼不太好的 <a class="header-anchor" href="#它有什麼不太好的-1" aria-label="Permalink to “它有什麼不太好的”">​</a></h4><p>Recalbox 比 RetroPie 擁有更少的仿真器、更少的自定義選項和更小的用户社區。</p><p>你的 Recalbox 裝備可能一直用於模擬器和 Kodi，安裝成什麼樣就是什麼樣。如果你想深入瞭解 Linux，你可能需要為 Raspbian 提供一個新的 SD 卡。</p><h4 id="它適用於誰-1" tabindex="-1">它適用於誰? <a class="header-anchor" href="#它適用於誰-1" aria-label="Permalink to “它適用於誰?”">​</a></h4><p>如果你想要絕對簡單的復古遊戲體驗，並且不想玩一些比較少見的遊戲平台模擬器，或者你害怕一些技術性工作（也沒有興趣去做），那麼 Recalbox 非常適合你。</p><p>對於大多數讀者來説，Recalbox 可能最適合推薦給你那些不太懂技術的朋友或親戚。它超級簡單的設置和幾乎沒什麼選項甚至可以讓你免去幫助他們解決問題。</p><h3 id="做個你自己的" tabindex="-1">做個你自己的 <a class="header-anchor" href="#做個你自己的" aria-label="Permalink to “做個你自己的”">​</a></h3><p>好，你可能已經注意到 Retropie 和 Recalbox 都是由許多相同的開源組件構建的。那麼為什麼不自己把它們組合在一起呢？</p><h4 id="介紹-2" tabindex="-1">介紹 <a class="header-anchor" href="#介紹-2" aria-label="Permalink to “介紹”">​</a></h4><p>無論你想要的是什麼，開源軟件的本質意味着你可以使用現有的模擬器套件作為起點，或者隨意使用它們。</p><h4 id="它有什麼好處-2" tabindex="-1">它有什麼好處 <a class="header-anchor" href="#它有什麼好處-2" aria-label="Permalink to “它有什麼好處”">​</a></h4>',16)),e("p",null,[a[18]||(a[18]=r("如果你想有自己的自定義界面，我想除了親自動手別無它法。這也是安裝在 RetroPie 中沒有的仿真器的方法，例如 ",-1)),l(t,{href:"http://www.mkw.me.uk/beebem/"},{default:o(()=>[...a[16]||(a[16]=[r("BeebEm",-1)])]),_:1}),a[19]||(a[19]=r(") 或 ",-1)),l(t,{href:"http://arcem.sourceforge.net/"},{default:o(()=>[...a[17]||(a[17]=[r("ArcEm",-1)])]),_:1}),a[20]||(a[20]=r("。",-1))]),a[60]||(a[60]=i('<h4 id="它有什麼不太好的-2" tabindex="-1">它有什麼不太好的 <a class="header-anchor" href="#它有什麼不太好的-2" aria-label="Permalink to “它有什麼不太好的”">​</a></h4><p>嗯，工作量有點大。</p><h4 id="它適用於誰-2" tabindex="-1">它適用於誰? <a class="header-anchor" href="#它適用於誰-2" aria-label="Permalink to “它適用於誰?”">​</a></h4><p>喜歡鼓搗的人，有動手能力的人，開發者，經驗豐富的業餘愛好者等。</p><h3 id="原生-risc-os-遊戲體驗" tabindex="-1">原生 RISC OS 遊戲體驗 <a class="header-anchor" href="#原生-risc-os-遊戲體驗" aria-label="Permalink to “原生 RISC OS 遊戲體驗”">​</a></h3>',5)),e("p",null,[a[22]||(a[22]=r("現在有一匹黑馬：",-1)),l(t,{href:"https://opensource.com/article/18/7/gentle-intro-risc-os"},{default:o(()=>[...a[21]||(a[21]=[r("RISC OS",-1)])]),_:1}),a[23]||(a[23]=r("，它是 ARM 設備的原始操作系統。",-1))]),a[61]||(a[61]=i('<h4 id="介紹-3" tabindex="-1">介紹 <a class="header-anchor" href="#介紹-3" aria-label="Permalink to “介紹”">​</a></h4><p>在 ARM 成為世界上最受歡迎的 CPU 架構之前，它最初是作為 Acorn Archimedes 的處理器而開發的。現在看起來這像是一種被遺忘的野獸，但是那幾年，它作為世界上最強大的台式計算機獨領風騷了好幾年，並且吸引了大量的遊戲開發項目。</p><p>樹莓派中的 ARM 處理器是 Archimedes 的曾孫輩的 CPU，所以我們仍然可以在其上安裝 RISC OS，只要做一點工作，就可以讓這些遊戲運行起來。這與我們到上面所介紹的仿真器方式不同，我們是在玩為該操作系統和 CPU 架構開發的遊戲。</p><h4 id="它有什麼好處-3" tabindex="-1">它有什麼好處 <a class="header-anchor" href="#它有什麼好處-3" aria-label="Permalink to “它有什麼好處”">​</a></h4><p>這是 RISC OS 的完美展現，這絕對是操作系統的瑰寶，非常值得一試。</p><p>事實上，你使用的是和以前幾乎相同的操作系統來加載和玩你的遊戲，這使得你的復古遊戲裝備像是一個時間機器一樣，這無疑為該項目增添了一些魅力和復古價值。</p><p>有一些精彩的遊戲只在 Archimedes 上發佈過。Archimedes 的巨大硬件優勢也意味着它通常擁有許多多平台遊戲大作的最佳圖形和最流暢的遊戲體驗。這類遊戲的版權持有者非常慷慨，可以合法地免費下載它們。</p><h4 id="它有什麼不太好的-3" tabindex="-1">它有什麼不太好的 <a class="header-anchor" href="#它有什麼不太好的-3" aria-label="Permalink to “它有什麼不太好的”">​</a></h4>',8)),e("p",null,[a[25]||(a[25]=r("安裝了 RISC OS 之後，它仍然需要一些努力才能讓遊戲運行起來。這是 ",-1)),l(t,{href:"https://blog.dxmtechsupport.com.au/playing-badass-acorn-archimedes-games-on-a-raspberry-pi/"},{default:o(()=>[...a[24]||(a[24]=[r("入門指南",-1)])]),_:1}),a[26]||(a[26]=r("。",-1))]),e("p",null,[a[29]||(a[29]=r("對於休息室來説，這絕對不是一個很好的全能選手。沒有什麼比 ",-1)),l(t,{href:"https://kodi.tv/"},{default:o(()=>[...a[27]||(a[27]=[r("Kodi",-1)])]),_:1}),a[30]||(a[30]=r(" 更好的了。它有一個網絡瀏覽器 ",-1)),l(t,{href:"https://www.netsurf-browser.org/"},{default:o(()=>[...a[28]||(a[28]=[r("NetSurf",-1)])]),_:1}),a[31]||(a[31]=r("，但它在支持現代 Web 方面還需要一些努力。你不會像使用模擬器套件那樣得到大量可以玩的遊戲。RISC OS Open 對於愛好者來説可以免費下載和使用，而且很多源代碼已經開源，儘管由於這個名字，它不是一個 100％ 的開源操作系統。",-1))]),a[62]||(a[62]=i('<h4 id="它適用於誰-3" tabindex="-1">它適用於誰? <a class="header-anchor" href="#它適用於誰-3" aria-label="Permalink to “它適用於誰?”">​</a></h4><p>這是專為追求新奇的人，絕對懷舊的人，想要探索一個來自上世紀 80 年代的有趣的操作系統的人，懷舊過去的 Acorn 機器的人，以及想要一個完全不同的懷舊遊戲項目的人而設計的。</p><h3 id="終端遊戲" tabindex="-1">終端遊戲 <a class="header-anchor" href="#終端遊戲" aria-label="Permalink to “終端遊戲”">​</a></h3><p>你是否真的需要安裝模擬器或者一個異域風情的操作系統才能重温輝煌的日子？為什麼不從命令列安裝一些原生 Linux 遊戲呢？</p><h4 id="介紹-4" tabindex="-1">介紹 <a class="header-anchor" href="#介紹-4" aria-label="Permalink to “介紹”">​</a></h4>',5)),e("p",null,[a[33]||(a[33]=r("有一系列原生的 Linux 遊戲經過測試可以在 ",-1)),l(t,{href:"https://www.raspberrypi.org/forums/viewtopic.php?f=78&t=51794"},{default:o(()=>[...a[32]||(a[32]=[r("樹莓派",-1)])]),_:1}),a[34]||(a[34]=r(" 上運行。",-1))]),a[63]||(a[63]=i('<h4 id="它有什麼好處-4" tabindex="-1">它有什麼好處 <a class="header-anchor" href="#它有什麼好處-4" aria-label="Permalink to “它有什麼好處”">​</a></h4><p>你可以使用命令列從程序包安裝其中的大部分，然後開始玩。很容易。如果你已經有了一個跑起來的 Raspbian，那麼它可能是你運行遊戲的最快途徑。</p><h4 id="它有什麼不太好的-4" tabindex="-1">它有什麼不太好的 <a class="header-anchor" href="#它有什麼不太好的-4" aria-label="Permalink to “它有什麼不太好的”">​</a></h4><p>嚴格來説，這並不是真正的復古遊戲。Linux 誕生於 1991 年，過了一段時間才成為了一個遊戲平台。這些不是經典的 8 位和 16 位時代的遊戲體驗；後來有一些移植的遊戲或受復古影響的遊戲。</p><h4 id="它適用於誰-4" tabindex="-1">它適用於誰? <a class="header-anchor" href="#它適用於誰-4" aria-label="Permalink to “它適用於誰?”">​</a></h4><p>如果你只是想找點樂子，這沒問題。但如果你想重温過去，那就不完全是這樣了。</p><hr>',7)),e("p",null,[a[36]||(a[36]=r("via: ",-1)),l(t,{href:"https://opensource.com/article/18/9/retro-gaming-raspberry-pi"},{default:o(()=>[...a[35]||(a[35]=[r("https://opensource.com/article/18/9/retro-gaming-raspberry-pi",-1)])]),_:1})]),e("p",null,[a[41]||(a[41]=r("作者：",-1)),l(t,{href:"https://opensource.com/users/dxmjames"},{default:o(()=>[...a[37]||(a[37]=[r("James Mawson",-1)])]),_:1}),a[42]||(a[42]=r(" 選題：",-1)),l(t,{href:"https://github.com/lujun9972"},{default:o(()=>[...a[38]||(a[38]=[r("lujun9972",-1)])]),_:1}),a[43]||(a[43]=r(" 譯者：",-1)),l(t,{href:"https://github.com/canhetingsky"},{default:o(()=>[...a[39]||(a[39]=[r("canhetingsky",-1)])]),_:1}),a[44]||(a[44]=r(" 校對：",-1)),l(t,{href:"https://github.com/wxy"},{default:o(()=>[...a[40]||(a[40]=[r("wxy",-1)])]),_:1})]),e("p",null,[a[47]||(a[47]=r("本文由 ",-1)),l(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...a[45]||(a[45]=[r("LCTT",-1)])]),_:1}),a[48]||(a[48]=r(" 原創編譯，",-1)),l(t,{href:"https://linux.cn/"},{default:o(()=>[...a[46]||(a[46]=[r("Linux中國",-1)])]),_:1}),a[49]||(a[49]=r(" 榮譽推出",-1))])])}const g=n(b,[["render",m]]);export{S as __pageData,g as default};
